<?php use App\Support\App;App::requireAdmin();$db=App::db();$rows=$db->query('SELECT * FROM products ORDER BY sort_order,id DESC')->fetchAll();$levels=$db->query('SELECT code,name FROM user_levels ORDER BY sort_order')->fetchAll();$title='Products';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row sm:items-end justify-between gap-3"><div><h1 class="page-title">Products</h1><p class="page-sub">Layanan, harga level, provider, CEIR dan routing WhatsApp.</p></div><div class="flex gap-2"><button class="btn" onclick="imp()"><i data-lucide="refresh-cw"></i>Sync CeirGo</button><a class="btn btn-dark" href="/admin/products/new"><i data-lucide="plus"></i>Add product</a></div></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[760px]"><thead><tr><th>Product</th><th>Code</th><th>Provider</th><th>CEIR</th><th>WA Group</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $p):?><tr class="border-t" style="border-color:var(--line)"><td><b><?=htmlspecialchars($p['name'])?></b><div class="text-xs text-zinc-500"><?=htmlspecialchars($p['processing_time']??'')?></div></td><td><code><?=htmlspecialchars($p['code'])?></code></td><td><span class="badge"><?=htmlspecialchars($p['provider_type'])?></span></td><td><?=$p['ceir_check_enabled']?'ON':'OFF'?></td><td class="max-w-40 truncate"><?=htmlspecialchars($p['whatsapp_group_id']??'-')?></td><td><span class="badge"><?=$p['is_active']?'ACTIVE':'OFF'?></span></td><td><button class="btn !py-1 !px-2 text-xs" onclick='openProduct(<?=htmlspecialchars(json_encode($p),ENT_QUOTES)?>)'>Edit</button></td></tr><?php endforeach?></tbody></table></div><dialog id="modal" class="product-modal"><form id="pf" class="saas-card p-6 w-[min(720px,94vw)] max-h-[90vh] overflow-auto space-y-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Product settings</h2><p class="text-sm text-zinc-500">Konfigurasi layanan dan harga.</p></div><button type="button" class="btn !p-2" onclick="closeProduct()">×</button></div><input type="hidden" name="id"><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm font-semibold">Product name<input class="field mt-2" name="name" required></label><label class="text-sm font-semibold">Code<input class="field mt-2 font-mono" name="code" required></label></div><label class="text-sm font-semibold">Description<textarea class="field mt-2" name="description" rows="2"></textarea></label><div class="grid sm:grid-cols-2 gap-4"><label class="text-sm font-semibold">Provider<select class="field mt-2" name="provider_type"><option value="manual">Manual / WhatsApp</option><option value="ceirgo">CeirGo API</option></select></label><label class="text-sm font-semibold">Processing time<input class="field mt-2" name="processing_time" placeholder="5-30 minutes"></label><label class="text-sm font-semibold">Provider service ID<input class="field mt-2" name="provider_service_id"></label><label class="text-sm font-semibold">Provider service code<input class="field mt-2" name="provider_service_code"></label><label class="text-sm font-semibold">Provider cost<input class="field mt-2" type="number" name="provider_cost" min="0"></label><label class="text-sm font-semibold">WhatsApp Group ID<input class="field mt-2" name="whatsapp_group_id" placeholder="1203...@g.us"></label></div><div><b class="text-sm">Selling prices</b><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-3 mt-3"><?php foreach($levels as $l):?><label class="text-xs font-semibold"><?=htmlspecialchars($l['name'])?><input class="field mt-1" type="number" min="0" name="prices[<?=$l['code']?>]" placeholder="0"></label><?php endforeach?></div></div><div class="grid sm:grid-cols-3 gap-3"><?php foreach([['ceir_check_enabled','CEIR precheck'],['auto_refund','Auto refund'],['is_active','Product active']] as $c):?><label class="toggle-row"><input type="checkbox" name="<?=$c[0]?>" value="1"><span><?=$c[1]?></span></label><?php endforeach?></div><button class="btn btn-dark w-full">Save product</button></form></dialog><script>
const productModal=document.getElementById('modal');
const productForm=document.getElementById('pf');
function openProduct(p=null){
 productForm.reset();
 productForm.elements['id'].value=p?.id||'';
 if(p) for(const [k,v] of Object.entries(p)){
  const el=productForm.elements[k];
  if(!el) continue;
  if(el.type==='checkbox') el.checked=!!Number(v); else el.value=v??'';
 }
 if(typeof productModal.showModal==='function') productModal.showModal(); else productModal.setAttribute('open','');
}
function closeProduct(){if(typeof productModal.close==='function')productModal.close();else productModal.removeAttribute('open')}
productForm.addEventListener('submit',async e=>{
 e.preventDefault();
 const fd=new FormData(productForm),o={prices:{}};
 for(const [k,v] of fd){const m=k.match(/^prices\[(.+)\]$/);if(m)o.prices[m[1]]=v;else o[k]=v}
 for(const k of ['ceir_check_enabled','auto_refund','is_active'])o[k]=fd.has(k)?1:0;
 try{
  const r=await fetch('/api/admin/products',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>','Accept':'application/json'},body:JSON.stringify(o)});
  const raw=await r.text(); let j; try{j=JSON.parse(raw)}catch(_){throw new Error('Server HTTP '+r.status+': '+raw.slice(0,300))}
  if(!r.ok||!j.ok)throw new Error(j.message||('HTTP '+r.status));
  await Swal.fire('Saved','Produk berhasil disimpan.','success'); location.reload();
 }catch(err){Swal.fire('Gagal menyimpan produk',err.message,'error')}
});
async function imp(){
 try{const r=await fetch('/api/admin/products/import-ceirgo',{method:'POST',headers:{'X-CSRF-Token':'<?=App::csrf()?>','Accept':'application/json'});const j=await r.json();Swal.fire(j.ok?'Sync complete':'Sync failed',j.message||((j.imported||0)+' services imported'),j.ok?'success':'error')}catch(e){Swal.fire('Sync failed',e.message,'error')}
}
</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>